 async function stageChange(id:string,fromId:string,toId:string,lostReasonId?:string,beforeId?:string|null){if(fromId===toId||busy||saving.current||!isValidStage(s,fromId)||!isValidStage(s,toId))return;const targetStage=stageOf(s,toId);if(targetStage?.kind==='lost'&&!lostReasonId){setLostReasonPick('');setLostPrompt({id,from:fromId,to:toId,beforeId});return}const wipCount=s.opportunities.filter(o=>o.stageId===toId&&o.id!==id).length;if(targetStage?.wipLimit!=null&&targetStage.wipMode==='warn'&&wipCount>=targetStage.wipLimit)toast.warning(`Límite WIP en ${targetStage.name} (${targetStage.wipLimit})`);setData(current=>current?.state?{...current,state:{...current.state,opportunities:current.state.opportunities.map(item=>item.id===id?{...item,stageId:toId,lostReasonId:targetStage?.kind==='lost'?lostReasonId||item.lostReasonId:item.lostReasonId}:item)}}:current);const cmd:Command={action:'stage',id,stageId:toId,expectedStageId:fromId,...(lostReasonId?{lostReasonId}:{}),...(beforeId!==undefined?{beforeId}:{})};if(await send(cmd)){setLostPrompt(null);if(isWonStage(s,toId))toast.success('¡Ganada!');else movedToast(stageName(s,toId),{action:'stage',id,stageId:fromId,expectedStageId:toId})}else {setData(current=>current?.state?{...current,state:{...current.state,opportunities:current.state.opportunities.map(item=>item.id===id&&item.stageId===toId?{...item,stageId:fromId}:item)}}:current);void load()}}
