 function openAgendaItem(item:AgendaItem){
  if(item.opportunityId&&item.companyId){setSelected({companyId:item.companyId,opportunityId:item.opportunityId});return}
  if(item.invoiceId){const inv=s.invoices.find(i=>i.id===item.invoiceId);if(inv){if(inv.paid||isDraft(inv)){setSelectedInvoiceId(inv.id)}else open('pay',{invoiceId:inv.id,amount:balance(s,inv),date:today(),method:'transfer',note:''})}return}
  if(item.taskId){const task=s.delivery.find(t=>t.id===item.taskId);if(task){changeView('Proyectos');setProjectFocus(task.projectId);open('delivery',task)};return}
  if(item.companyId)setSelected({companyId:item.companyId});
 }
