<InvoicePanel open={!!selectedInvoice} invoice={selectedInvoice} state={s} companyName={selectedInvoice?company(companyForOrder(s,selectedInvoice.orderId))?.name||'':''} companyEmail={selectedInvoice?company(companyForOrder(s,selectedInvoice.orderId))?.email||'':''} orderTitle={selectedInvoice?s.orders.find(o=>o.id===selectedInvoice.orderId)?.title||'':''} busy={busy} onClose={()=>setSelectedInvoiceId(null)} onPay={()=>selectedInvoice&&open('pay',{invoiceId:selectedInvoice.id,amount:balance(s,selectedInvoice),date:today(),method:'transfer',note:''})} onEdit={()=>selectedInvoice&&open('editInvoice',selectedInvoice)} onIssue={async()=>{if(!selectedInvoice||busy)return;if(await send({action:'issueInvoice',id:selectedInvoice.id}))toast.success('Factura emitida')}} onCredit={async()=>{if(!selectedInvoice||busy)return;if(await send({action:'creditInvoice',id:selectedInvoice.id})){toast.success('Factura anulada');setSelectedInvoiceId(null)}}} onVoidPayment={async id=>{if(busy)return;if(await send({action:'voidPayment',id}))toast.success('Cobro anulado')}} onSent={async()=>{if(!selectedInvoice||busy)return;try{const r=await fetch('/api/invoice-send',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:selectedInvoice.id,revision:data?.revision})});const d=await r.json() as any;if(!r.ok)throw new Error(d.error||'No se pudo enviar');setData(d);toast.success('Factura enviada')}catch(e){toast.error((e as Error).message)}}}/>
