 const input=(key:string,label:string,type='text',props:any={})=><Field label={label}><input type={type} value={r[key]??''} onChange={e=>set(key,type==='number'?(e.target.value===''?'':Number(e.target.value)):e.target.value)} onInput={e=>{if(type==='date')set(key,e.currentTarget.value)}} {...props}/></Field>;
 const pick=(key:string,label:string,options:any[])=><Field label={label}><Pick value={String(r[key]??'')} onChange={v=>set(key,key==='lineIndex'?Number(v):v)} label={label} options={options}/></Field>;
 const oppOptions=[{value:'',label:'Selecciona una oportunidad'},...s.opportunities.map(o=>({value:o.id,label:`${s.companies.find(c=>c.id===o.companyId)?.name} · ${o.title}`}))];
 const taskOptions=[{value:'',label:'Selecciona una tarea'},...s.delivery.map(t=>({value:t.id,label:`${s.projects.find(p=>p.id===t.projectId)?.title} · ${t.title}`}))];
 const order=s.orders.find(o=>o.id===r.orderId);
 const eligibleHours=order?pendingHours(s,order.id):[];
 const assigneeKnown=!r.assignee||teamMembers.includes(r.assignee);
